{S} .cs-art-panel { border: 4px solid var(--cs-ink); border-radius: var(--cs-art-r-card); box-shadow: 8px 8px 0 var(--cs-ink), 0 0 0 3px var(--cs-bg); }
{S} .cs-items .cs-item { background-image: linear-gradient(to bottom, var(--cs-scrim-to) 0%, var(--cs-accent) 100%); }
{S} .cs-item[data-hi] { background-image: repeating-linear-gradient(135deg, var(--cs-line) 0 4px, transparent 4px 8px); }
{S}[data-tone="invert"] .cs-rail-seg { background-color: var(--cs-line); }
{S}[data-recipe="under"] .cs-anchor-slot, {S}[data-anchor-kind="chart"] .cs-art-svg { gap: 24px; }
{S} .cs-icon, {S} .cs-marks, {S} .cs-thread, {S} .cs-rail { display: block; }
{S} .cs-art-label { padding-inline: 12px; }
